function maxNumOfMarkedIndices(nums) {
  const n = nums.length;
  const memo = new Map();
  const solve = (mask) => {
    if (memo.has(mask)) return memo.get(mask);
    let i = 0;
    while (i < n && (mask >> i) & 1) i++;
    if (i === n) return 0;
    let best = solve(mask | (1 << i));
    for (let j = i + 1; j < n; j++) {
      if ((mask >> j) & 1) continue;
      if (2 * nums[i] <= nums[j] || 2 * nums[j] <= nums[i]) {
        best = Math.max(best, 2 + solve(mask | (1 << i) | (1 << j)));
      }
    }
    memo.set(mask, best);
    return best;
  };
  return solve(0);
}

